Given a linked list and a value x, partition it such that all nodes less than x come first, then all nodes with a value equal to x, and finally nodes with a vaxlue greater than x. The original relative order of the nodes in each of the three partitions should be preserved.Examples: Input : 1 -> 4 -> 3 -> 2 -> 5 -> 2 -> 3, x = 3Output: 1 -> 2 -> 2 -> 3 -> 3 -> 4 -> 5Explanation: In the below linked list, all nodes with value less than 3 are on the left and rest of the nodes on the right by maintaining the relative order. Input: 10 -> 4 -> 20 -> 10 -> 3, x = 3Output: 3 -> 10 -> 4 -> 20 -> 10Try It Yourself[Approach] Three Partition Method – O(n) Time and O(1) SpaceThe idea is to use three dummy nodes to create three separate partitions: less, equal, and greater. As the list is traversed, each node is added to its corresponding partition. Once all nodes are processed, the partitions are connected to form the final list.
            C++

    #include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;

    Node(int val) {
        data = val;
        next = NULL;
    }
};

Node* partition(Node* head, int x) {
    // Dummy head for nodes less than x
    Node* lessHead = new Node(0); 

    // Dummy head for nodes equal to x
    Node* equalHead = new Node(0); 

    // Dummy head for nodes greater than or equal to x
    Node* greaterHead = new Node(0);

    Node* less = lessHead;
    Node* equal = equalHead;
    Node* greater = greaterHead;

    Node* curr = head;

    while (curr != NULL) {
        if (curr->data < x) {
            less->next = curr;
            less = less->next;
        } else if (curr->data == x) {
            equal->next = curr;
            equal = equal->next;
        } else {
            greater->next = curr;
            greater = greater->next;
        }
        curr = curr->next;
    }

    // Connect the partitions together
    greater->next = NULL;  

    // Connect equal to greater
    equal->next = greaterHead->next; 

    // Connect less to equal
    less->next = equalHead->next;  

    // New head of the rearranged list
    Node* newHead = lessHead->next; 

    // Clean up dummy nodes
    delete lessHead;
    delete equalHead;
    delete greaterHead;

    return newHead;
}

void printList(Node* head) {
    Node* curr = head;
    while (curr != NULL) {
        cout << curr->data << " ";
        curr = curr->next;
    }
    cout << endl;
}

int main() {
    // Creating the linked list: 1 -> 4 -> 3 -> 2 -> 5 -> 2
    Node* head = new Node(1);
    head->next = new Node(4);
    head->next->next = new Node(3);
    head->next->next->next = new Node(2);
    head->next->next->next->next = new Node(5);
    head->next->next->next->next->next = new Node(2);

  	int x = 3;
    head = partition(head, x);
    printList(head);

    return 0;
}


